import{_ as i,c as l,aU as t,a as e}from"./chunks/framework.DP-R0N-M.js";const d=JSON.parse('{"title":"电视剧","description":"","frontmatter":{},"headers":[],"relativePath":"note/movie/tv.md","filePath":"note/movie/tv.md","lastUpdated":1758205906000}'),p={name:"note/movie/tv.md"};function m(r,a,h,o,c,s){return e(),l("div",null,[...a[0]||(a[0]=[t('<h1 id="电视剧" tabindex="-1">电视剧 <a class="header-anchor" href="#电视剧" aria-label="Permalink to &quot;电视剧&quot;">​</a></h1><p>下面都是我看过的电视剧，啥时候想起来了就更新一波。好看的电视剧太多太多了....</p><p>有些电视剧拍的是真的好，没看过真的是人生一大遗憾。比如 《我的团长我的团》 《风筝》 《潜伏》...</p><p>里面不仅有很多很多的名场面，还能学习到那个时候的历史背景和历史人物，轻则让你记住几个梗，中则让你了解当时的历史，重则让你灵魂升华一下子</p><h2 id="士兵突击" tabindex="-1">士兵突击 <a class="header-anchor" href="#士兵突击" aria-label="Permalink to &quot;士兵突击&quot;">​</a></h2><ul><li>2006-12-24 中国大陆</li><li>类型：剧情 励志 军旅</li><li>主演：王宝强 陈思诚 段奕宏 张译 邢佳栋</li><li>百科：木讷的许三多(王宝强)没进军营,就因看见坦克时“举手投降”招来以“不抛弃、不放弃”精神闻名全团的“钢七连”连长高城(张国强)的反感,入营后,班长史今(张译)成为他的依靠,</li></ul><p>男人必看系列！！！最好看的军旅剧，没有之一</p><p><img src="https://img1.baidu.com/it/u=269822083,3724023344&amp;fm=253&amp;fmt=auto&amp;app=138&amp;f=JPEG?w=528&amp;h=708" alt=""></p><h2 id="我的团长我的团" tabindex="-1">我的团长我的团 <a class="header-anchor" href="#我的团长我的团" aria-label="Permalink to &quot;我的团长我的团&quot;">​</a></h2><ul><li>2009-03-05 中国大陆</li><li>类型：战争 历史</li><li>主演：段奕宏 张译 张国强 邢佳栋 李晨</li><li>百科：1942年,中缅边境有座叫禅达的小镇。时不时受到炮火袭击的地方,聚集着一群来自五湖四海的溃兵。他们是小太爷孟烦了(张译 饰)、军医郝兽医(罗京民 饰)、东北佬迷龙(张国强 饰</li></ul><p>男人必看系列！！！ 最好看的抗日战争剧，没有之一</p><p><img src="https://q2.itc.cn/images01/20240317/9b5fbdceb6824c87a25e702cd1662245.jpeg" alt=""></p><h2 id="我的兄弟叫顺溜" tabindex="-1">我的兄弟叫顺溜 <a class="header-anchor" href="#我的兄弟叫顺溜" aria-label="Permalink to &quot;我的兄弟叫顺溜&quot;">​</a></h2><ul><li>2009-06-26 中国大陆</li><li>类型：军事 战争 历史</li><li>主演：王宝强 张国强 孙逊 徐洪浩 霍青</li><li>百科：新四军小战士顺溜(王宝强 饰)在伏击汉奸司令吴大疤拉(杨子骅 饰)时竟打掉了自己六分区司令陈大雷(张国强 饰)的头盔。陈大雷赏识百步穿杨的神枪手顺溜,与他称兄道弟,并给顺溜起了...</li></ul><p><code>鬼子杀了我们那么多人~！现在打败了，枪一扔不打了~！ 回家~！连畜牲也要回家~！ 他们评什么不打~！ 鬼子都可以回家，可我的家呢~！</code></p><p><img src="https://img0.baidu.com/it/u=3978705399,2053121356&amp;fm=253&amp;fmt=auto&amp;app=138&amp;f=JPEG?w=1023&amp;h=718" alt=""></p><h2 id="人民的名义" tabindex="-1">人民的名义 <a class="header-anchor" href="#人民的名义" aria-label="Permalink to &quot;人民的名义&quot;">​</a></h2><ul><li>2017-03-28 中国大陆</li><li>类型：犯罪 剧情 都市</li><li>主演：陆毅 张丰毅 吴刚 柯蓝 张志坚</li><li>百科：夜幕下的汉东省京州市,看似平静的官场霎时间阴云密布。国家部委项目处处长赵德汉涉嫌受贿,遭到最高人民检察院反贪总局侦查处处长侯亮平(陆毅 饰)的突击调查。与此同时,侯亮平要求在京...</li></ul><p><img src="https://pic.rmb.bdstatic.com/6d772f85600a40b5ea6d2dd49e6caf28.jpg@h_1280" alt=""></p><h2 id="雪豹" tabindex="-1">雪豹 <a class="header-anchor" href="#雪豹" aria-label="Permalink to &quot;雪豹&quot;">​</a></h2><ul><li>2014-09-03 中国大陆</li><li>类型：战争</li><li>主演：张若昀 高洋 毛晓彤 刘广楠 张永刚</li><li>百科：《新雪豹》改编自业余狙击手的 网络小说《特战先驱》,该小说2009 年曾改编拍摄成由文章主演的电视剧 《雪豹》,播出后大获好评。时隔三 年后,旧版《雪豹》的原版人马再次 联手打</li></ul><p><img src="https://img1.baidu.com/it/u=3538698221,1447238211&amp;fm=253&amp;fmt=auto&amp;app=138&amp;f=JPEG?w=800&amp;h=1201" alt=""></p><h2 id="少帅" tabindex="-1">少帅 <a class="header-anchor" href="#少帅" aria-label="Permalink to &quot;少帅&quot;">​</a></h2><ul><li>2015-12-29 中国大陆</li><li>类型：历史 剧情 战争</li><li>主演：文章 李雪健 宋佳 张歆怡 黄品沅</li><li>百科：大雪纷飞的严冬,一辆马车载着张学良及姐弟首芳、学铭从老家来到奉天。他们一身縗絰,而父亲张作霖(李雪健 饰)则踌躇满志,正准备做一番大事业。少年时代的小六子耿直鲁莽,他敢于顶撞父..</li></ul><p><img src="https://img1.baidu.com/it/u=2450091339,1769414502&amp;fm=253&amp;fmt=auto&amp;app=138&amp;f=JPEG?w=342&amp;h=500" alt=""></p><h2 id="风筝" tabindex="-1">风筝 <a class="header-anchor" href="#风筝" aria-label="Permalink to &quot;风筝&quot;">​</a></h2><ul><li>2017-12-17 中国大陆</li><li>类型：悬疑 谍战 剧情</li><li>主演：柳云龙 罗海琼 李小冉 齐欢 孙斌</li><li>百科：重庆军统王牌特工郑耀先,以狡黠机智和心狠手辣闻名。郑耀先其实就是潜伏在军统的共产党特工“风筝”,为了确保“风筝”像一把尖刀始终刺在敌人的心脏上,在最关键时刻给国民党致命一击,郑</li></ul><p>6哥太有魅力了，最好看的谍战片</p><p><img src="https://img1.baidu.com/it/u=4269240848,3299818865&amp;fm=253&amp;fmt=auto&amp;app=120&amp;f=JPEG?w=1416&amp;h=800" alt=""></p><h2 id="悬崖" tabindex="-1">悬崖 <a class="header-anchor" href="#悬崖" aria-label="Permalink to &quot;悬崖&quot;">​</a></h2><ul><li>2012-01-01 中国大陆</li><li>类型：谍战 历史 战争</li><li>主演：张嘉益 宋佳 程煜 李洪涛 咏梅 Mei Yong</li><li>百科：上世纪30年代末,古老的中华大地正经受着最为苦难的时刻。外有日寇铁蹄进犯,内有不同派别势力的斗争碾压,战火连绵,生灵涂炭。为了获取重要的情报,共产党方面派出周乙(张嘉译 饰)和.. <img src="https://img2.baidu.com/it/u=3074966680,565468719&amp;fm=253&amp;fmt=auto&amp;app=138&amp;f=JPEG?w=500&amp;h=701" alt=""></li></ul><h2 id="后厨" tabindex="-1">后厨 <a class="header-anchor" href="#后厨" aria-label="Permalink to &quot;后厨&quot;">​</a></h2><ul><li>2012-07-05 中国大陆</li><li>类型：爱情 喜剧</li><li>导演：史晨风</li><li>主演：小沈阳 海清 章婷婷 姜彤 赵峥</li><li>简介：该剧讲述了行政总厨徐冰和刑满释放人员时慧宝的故事。起初他们分别在不同饭店后厨较量，后来时转投徐所在酒店。两人性格相违且曾是对手，继续比拼。在这一过程中，两人各自经历着亲情和爱情的历练，彼此的隔阂也渐渐消除</li></ul><p>这个剧是我最近看的，当时是在抖音刷到了一个片段，就是第一集小沈阳去找工作，给客人做了一份蛋炒蛋哪个片段，感觉挺有意思，所以 就搜了原片看，确实还挺有意思的，很搞笑，一个周末可就看完了。</p><p><img src="https://gimg2.baidu.com/image_search/src=http%3A%2F%2Fimg.ivsky.com%2Fimg%2Fbizhi%2Fpic%2F201211%2F11%2Fhouchu.jpg%3Fdownload&amp;refer=http%3A%2F%2Fimg.ivsky.com&amp;app=2002&amp;size=f9999,10000&amp;q=a80&amp;n=0&amp;g=0n&amp;fmt=auto?sec=1728396936&amp;t=e0397141af91eb4043628af291c4f019" alt=""></p><h2 id="岁月" tabindex="-1">岁月 <a class="header-anchor" href="#岁月" aria-label="Permalink to &quot;岁月&quot;">​</a></h2><ul><li>2008 中国大陆</li><li>类型：剧情家庭</li><li>主演：胡军梅婷王彤于和伟王早来</li><li>百科：现实与想象总是有很大差距,梁致远(胡军 饰)走出校门踏入社会后,既感到社会上人事关系的复杂,人与人相处仿佛在演戏,你永远不知道对方说的哪句话是真的,只有小心揣测别人的心思。</li></ul><p><img src="https://m.ykimg.com/052600005D19C171425BD9189FCFD496" alt=""></p><h2 id="抹布女也有春天" tabindex="-1">抹布女也有春天 <a class="header-anchor" href="#抹布女也有春天" aria-label="Permalink to &quot;抹布女也有春天&quot;">​</a></h2><ul><li>2013-09-02 中国大陆</li><li>类型：爱情 都市 喜剧</li><li>主演：海清 张译 芦芳生 吕夏 傅迦</li><li>简介：该剧讲述的是4S店的汽修师罗小葱为了爱人文艺漫画男吴桐放弃一切，全心全意帮助爱人的事业，待爱人事业成功后，却惨遭其抛弃，成为“抹布女”的浪漫谐趣情感故事</li></ul><p>这个剧也是最近看的，刷抖音看到的片段给推荐的，就是罗小葱去给富二代修车要1w2，富二代问为啥这么贵，因为心情不好。正好刚刚后厨看完，海清的剧 还是挺有意思的，所以就搜了原片，挺搞笑的，里面罗小葱和吴桐饰演的夫妻还是挺让我羡慕的。</p><p><img src="https://i-7.vcimg.com/trim/c398ffb4c787bfc0bad79c36bc882b90140338/trim.jpg" alt=""></p><h2 id="乔家儿女" tabindex="-1">乔家儿女 <a class="header-anchor" href="#乔家儿女" aria-label="Permalink to &quot;乔家儿女&quot;">​</a></h2><ul><li>2021-08-17 中国大陆</li><li>类型：家庭剧情</li><li>主演：白宇 宋祖儿 毛晓彤 张晚意 周翊然</li><li>简介：百科乔家的母亲在生第五个孩子乔七七(周翊然 饰)的时候去世了,父亲乔祖望(刘钧 饰)是一个粗暴又自私的人,一成(白宇 饰)、二强(张晚意 饰)、三丽(毛晓彤 饰)、四美(宋祖儿 饰)、七七,乔家的五个孩子,在艰苦的岁月里相依为命。乔一成作为长子,一路照顾着弟弟妹妹们长大,却又一路活在优秀的表哥齐唯民(李佳航 饰)的阴影下。乔一成考上了师范大学,弟妹们也互相拉扯着长大了,这一家子逐渐脱离了贫困。生活的考验和照拂都不会缺席,几个人的学业、婚姻、工作都让乔一成操碎了心,而他自己的两次婚姻也牵动着这个大家庭的喜和忧。他们经历过痛苦的考验,也迎来过希望和温暖,一路走得跌跌撞撞又热热闹闹。说不上美满,也各有缺憾,就如乔一成所感触到的,虽然“各人有各人的泥潭”,但为了那向上的一点光明,大家都在努力生活。</li></ul><p>非常好看的一部剧，两天看完了，评论里面都是在说乔家的4个倒霉蛋。别说，里面的女演员都挺漂亮的。</p><p><img src="https://images.uiiiuiii.com/wp-content/uploads/2021/09/i-poster-zyj210901-3-6.jpg" alt=""></p><h2 id="凡人歌" tabindex="-1">凡人歌 <a class="header-anchor" href="#凡人歌" aria-label="Permalink to &quot;凡人歌&quot;">​</a></h2><ul><li>2024-08-31 中国大陆</li><li>类型：搞笑 剧情 生活</li><li>主演：殷桃 王骁 章若楠 秦俊杰 张哲华</li><li>简介：该剧讲述了三对30岁、40岁的夫妻或情侣在快节奏的大环境下,被生活围追堵截,努力自救,从而实现各自人生价值的故事。当了五年全职主妇的沈琳(殷桃 饰)遭遇丈夫那伟(王骁 饰)失业</li></ul><p>目前正在看的一部剧，感觉还是挺好看的，不过啊，里面还是凡人的起点太高了，一个是公司副总，北京有车有房还有保姆，另一个是年薪百万的IT精英。 另外一个是公务员... 这是凡人天花板吧</p><p><img src="https://picx.zhimg.com/70/v2-02b26e95a79563eba8bbc107b0d3c741_1440w.avis?source=172ae18b&amp;biz_tag=Post" alt=""></p><h2 id="二十不惑" tabindex="-1">二十不惑 <a class="header-anchor" href="#二十不惑" aria-label="Permalink to &quot;二十不惑&quot;">​</a></h2><ul><li>2020-07-14 中国大陆</li><li>类型：励志 都市 言情</li><li>主演：关晓彤 金世佳 牛骏峰 卜冠今 李庚希</li><li>简介：讲述了四个即将毕业的大学女生,在即将迈向社会的一年中,经历一系列挫折,但最终在生活和职场上收获了爱与成长的故事。站在校园与社会的分水岭,每个人都有自己要打败的困难和要解决的难题</li></ul><p>挺有意思的，推荐！！！</p><p><img src="https://hancheng.ishaanxi.com/upload/resources/image/2020/07/23/242970_800x9999.jpeg" alt=""></p><h2 id="父母爱情" tabindex="-1">父母爱情 <a class="header-anchor" href="#父母爱情" aria-label="Permalink to &quot;父母爱情&quot;">​</a></h2><ul><li>2014-02-02 中国大陆</li><li>类型：爱情 家庭 年代</li><li>主演：郭涛 梅婷 刘琳 任帅 刘奕君</li><li>百科: 江德福(郭涛 饰)和安杰(梅婷 饰)这对男女可真是八竿子够不上关系的两个人。 他们一个是年轻有为、干练果敢的海军军官,一个是从小养尊处优、娇媚华贵的资本家小姐,但20世纪50年代的沧桑巨变让他们俩人走到了一起。江德福在舞会上结识美丽的安杰,虽然他冒冒失失,又 是个目不识丁的大老粗,经过一番周折他们终于组建了成分不相匹配的小家庭。</li></ul><p>非常好看！！！ 快给我看！！！</p><p><img src="https://wx2.sinaimg.cn/mw690/0070fLwFly1hs2fyva6htj30u016f7e7.jpg" alt=""></p><h2 id="乔家大院" tabindex="-1">乔家大院 <a class="header-anchor" href="#乔家大院" aria-label="Permalink to &quot;乔家大院&quot;">​</a></h2><ul><li>2006-02-13 中国大陆</li><li>类型：传记 剧情</li><li>主演：陈建斌 蒋勤勤 马伊琍 赵丽娟 倪大红</li><li>百科: 该剧以乔家大院为背景，讲述了一代传奇晋商乔致庸弃文从商，在经历千难万险后终于实现货通天下、汇通天下的故事</li></ul><p><img src="https://p0.itc.cn/images01/20210523/9912c3b56d144dacbb494e4b23e0aae9.png" alt=""></p><h2 id="大宅门" tabindex="-1">大宅门 <a class="header-anchor" href="#大宅门" aria-label="Permalink to &quot;大宅门&quot;">​</a></h2><ul><li>2001-04-15 中国大陆</li><li>类型：家庭 历史 剧情</li><li>主演：斯琴高娃 陈宝国 刘佩琦 雷恪生 何赛飞</li><li>百科：《大宅门》由郭宝昌出任编剧和导演,2001年荣获中央电视台收视冠军。 剧中讲述了医药世家白府经历清末、民国、军阀混战、解放等时期的浮沉变化,忠实地反映了同仁堂这个大家族随着国家、民族的历史发展而发展的渐变过程。故事横跨光绪年间、1900年八国联军侵入北京、1911年清朝覆灭、1931年九一八事变、1937年七七卢沟桥事变。官场恩怨、情场爱恨、商场输赢。谱写了一曲“宅门”史,展一幅波澜壮阔动荡社会生活画卷,父母子孙、妻妾丫妓、至爱亲朋;“宅门”人,谱一曲世态炎凉悲欢离合命运之歌。</li></ul><p><img src="https://pic.rmb.bdstatic.com/bjh/down/556be365ec414c29aad70b2ea04466b5.jpeg" alt=""></p><h2 id="寻秦记" tabindex="-1">寻秦记 <a class="header-anchor" href="#寻秦记" aria-label="Permalink to &quot;寻秦记&quot;">​</a></h2><ul><li>2001-10-15 中国香港</li><li>类型：历史 奇幻 搞笑</li><li>主演：古天乐 江华 宣萱 郭羡妮 林峯</li><li>百科：21世纪特种部队人员项少龙(古天乐 饰)决意要参加穿梭时空的研究,是为了要挽回自己的爱情。但由于时光机的数据出错,把少龙带到了战国时期。 当时的嬴政(林峰 饰)还没有登上帝位,更被囚禁于赵国。少龙为了能返回未来,便不惜一切帮助嬴政顺利登上帝位。由于少龙的机智过人与特殊身份,他的能力得到了众人的赏识,因此他也遭到了多方奸狡之人的暗算。 在腹背受敌的情况下,生性风流的少龙也纠缠上一段复杂的四角恋爱关系。到底少龙能否协助嬴政赢得天下呢?他会如何处理自己与隔世恋人的情缘呢?</li></ul><p>穿越剧的鼻祖，非常好看。</p><p><img src="https://img0.baidu.com/it/u=3244459068,335203146&amp;fm=253&amp;fmt=auto&amp;app=138&amp;f=JPEG?w=425&amp;h=638" alt=""></p><h2 id="荣归" tabindex="-1">荣归 <a class="header-anchor" href="#荣归" aria-label="Permalink to &quot;荣归&quot;">​</a></h2><ul><li>2007-07-15 中国大陆</li><li>类型：剧情 历史</li><li>主演：郑少秋 焦晃 归亚蕾 吴军忱 林雨申</li><li>百科：香港回归祖国后,荣凯集团总裁李国凯(郑少秋 饰)得以和在北京的胞兄李国荣(焦晃 饰)团聚。由于之前一直生活在不同的社会制度下,世界观、人生观不同,哥俩不久产生了摩擦。亚洲金融危。</li></ul><p>非常非常非常好看，感人</p><p><img src="https://m.ykimg.com/053500005F55E52D13EA350B24387099?x-oss-process=image/resize,w_750/interlace,1/quality,Q_100/sharpen,100" alt=""></p><h2 id="青瓷" tabindex="-1">青瓷 <a class="header-anchor" href="#青瓷" aria-label="Permalink to &quot;青瓷&quot;">​</a></h2><ul><li>2012-06-04 中国大陆</li><li>类型：爱情 都市 剧情</li><li>主演：王志文 张国立 韩雨芹 王海燕 杜江</li><li>百科：张仲平(王志文 饰)是3D拍卖公司老总,他派外甥徐艺(杜江 饰)带50万现金找胜利大厦开发商左达(汪俊 饰),以换取该大厦拍卖推荐函,嗜赌成性的左达与徐艺赌输赢,最终以自己跳楼自杀收场,而省下50万的徐艺萌生离开舅舅、自立门户的念头。电视台记者曾真(韩雨芹 饰)是徐艺的 暗恋对象,他曾向其表白但遭拒绝。后偶遇暗恋自己的师妹辛然(李菲儿 饰),通过一次突发的“英雄救美”事件,特别是知道辛然的父亲周运年(郑晓宁 饰)是副市长后,他马上与辛然进入热恋之中。底气十足的徐艺要自办拍卖公司令张仲平十分意外,但此时的徐艺今非昔比,他频频用各种潜规则拓展自己的拍卖业务,这令业内同行深感不满,他们决定出招了......</li></ul><p>非常好看！！！</p><p><img src="https://img1.baidu.com/it/u=3324146466,3908476156&amp;fm=253&amp;fmt=auto&amp;app=138&amp;f=JPEG?w=500&amp;h=331" alt=""></p><h2 id="大染坊" tabindex="-1">大染坊 <a class="header-anchor" href="#大染坊" aria-label="Permalink to &quot;大染坊&quot;">​</a></h2><ul><li>2003-10-09 中国大陆</li><li>类型：历史 商战 剧情</li><li>主演：侯勇 牛犇 罗刚 萨日娜 尹双双</li><li>百科：清朝末年,一派萧瑟之气。父母早亡无家可归的十五岁少年陈六子流落街头,靠着要饭存活。但六子天子聪颖,机智灵活,时不时去听听说书,了解外面的世界。某个冬天,六子得到了饭店伙计锁子叔的照顾,让六子感激了一生。冻得没办法的六子倒在了周村通和染坊门前,早晨出来扫雪的周掌柜,救下了六子,且把他认为义子,取名陈寿亭(侯勇 饰)。就这样,陈寿亭开始了在通和染坊的生活。时光荏苒,十年间,寿亭通过自己的勤奋和机智,熟练的掌握了染坊的所有技艺和事项,把通和染坊经营成了周村的最大染坊,引起了大亨染坊老板的觊觎。他想通过贿赂把寿亭挖过来,寿亭却意志坚定,连绑架他的土匪都对他心生敬佩。就这样,周村上下无人不知晓陈寿亭。 大户卢家老爷看中了寿亭,想让其去青岛协助从德国归来学印染的儿子卢家驹(罗刚 饰)。寿亭因此走上了工业印染之路和创业之路</li></ul><p><img src="https://img0.baidu.com/it/u=1399766421,2691821907&amp;fm=253&amp;fmt=auto&amp;app=138&amp;f=JPEG?w=500&amp;h=667" alt=""></p><h2 id="无所畏惧" tabindex="-1">无所畏惧 <a class="header-anchor" href="#无所畏惧" aria-label="Permalink to &quot;无所畏惧&quot;">​</a></h2><ul><li>2023-11-03 中国大陆</li><li>类型：剧情 生活 家庭</li><li>主演：热依扎 王阳 啜妮 沈羽洁 李煜</li></ul><p>热依扎很漂亮</p><p><img src="https://p4.itc.cn/images01/20231122/354d982921384d74ac02b9e58ebddb6b.jpeg" alt=""></p><h2 id="追风者" tabindex="-1">追风者 <a class="header-anchor" href="#追风者" aria-label="Permalink to &quot;追风者&quot;">​</a></h2><ul><li>2024-03-21 中国大陆</li><li>类型：剧情</li><li>主演：王一博 李沁 王阳 张天阳 王学圻</li><li>百科：1930年的上海,魏若来作为国民党中央银行的普通职员,凭借出色的工作能力,逐步得到高级顾问沈图南的赏识。在此过程中,魏若来见到了国民党金融领域的诸多腐败与黑暗。彷徨苦闷中,共产党员沈近真用马克思主义这盏指路明灯照亮了魏若来的内心,不同的选择让他与沈图南最终分道扬镳。在组织的安排下,魏若来、沈近真从上海转移到江西。魏若来在党的坚强领导下,参与到粉碎国民党对中央苏区的经济封锁这一没有硝烟的战争中,逐步成长为我党经济战线上独当一面的红色金融家。</li></ul><p>王一博演技很亮眼，挺好看的，推荐</p><p><img src="https://img0.baidu.com/it/u=3447828400,3061797274&amp;fm=253&amp;fmt=auto&amp;app=138&amp;f=JPEG?w=800&amp;h=1057" alt=""></p><h2 id="山海情" tabindex="-1">山海情 <a class="header-anchor" href="#山海情" aria-label="Permalink to &quot;山海情&quot;">​</a></h2><ul><li>2021-01-12 中国大陆</li><li>类型：农村 剧情 当代</li><li>主演：黄轩 张嘉益 闫妮 黄觉 姚晨</li><li>百科：上世纪90年代,从宁夏贫瘠甲天下的西海固地区搬迁到玉泉营地区的移民们,从无到有地建设着他们的新家园,村干部马得福(黄轩 饰)操心着通电、灌溉用水等桩桩件件的问题,他足够努力,却不自信未来什么时候来。直到国家新的扶贫政策出台,福建对宁夏的扶贫事业进行对口援助,并建立了合作样板闽宁村,陈金山(郭京飞 饰)、凌一农(黄觉 饰)等一批优秀的福建干部、技术人员为闽宁镇洒下奋斗的汗水,帮助得福找到了未来的方向,白麦苗(黄尧 饰)、马得宝(白宇帆 饰)、李水花(热依扎 饰)等村里的年轻人也通过劳务输入、发展庭院经济等收获了自信。在发展的过程中,传统与现代,物质文明与精神文明,寻根与断根等问题不断突显,对于马喊水(张嘉益 饰)、白校长(祖峰 饰)、李大有(尤勇智 饰)这些上一辈的人们而言,挑战和转变也在不断发生着。从西海固走出的人们没有忘记他们的初心,他们没有断根,而是把根扎在了这片更肥沃的地方,互相扶持着走上了康庄大道。</li></ul><p>非常棒的片子！！！！！</p><p><img src="https://boot-img.xuexi.cn/contribute_img/20210112195409/16827471134947263.jpg" alt=""></p><h2 id="白鹿原" tabindex="-1">白鹿原 <a class="header-anchor" href="#白鹿原" aria-label="Permalink to &quot;白鹿原&quot;">​</a></h2><ul><li>2017-04-16 中国大陆</li><li>类型：年代 剧情</li><li>主演：张嘉益 秦海璐 何冰 刘佩琦 李洪涛</li><li>百科：20世纪初,渭河平原滋水县有一个白鹿原,生活着一群普通却不平凡的百姓。白鹿两家合而为村,相互依存又关系微妙。少东家白嘉轩(张嘉益 饰)与鹿子霖(何冰 饰)为了族长位置暗自较劲儿。嘉轩娶回逃难的仙草(秦海璐 饰),先后生下孝文、孝武和白灵三个孩子。鹿子霖爱走歪门邪道,一心 让两个儿子兆鹏和兆海光宗耀祖。生于乱世,城头变幻大王旗。但不管谁做官,总不免鱼肉底层的百姓。白嘉轩顶着各方的压力,成为白鹿原上响当当的一根硬骨头。可是孩子们长大后,却各有各的主意。拒绝包办婚姻的兆鹏(雷佳音 饰)加入共产党,自己的弟弟则成为国军军官。白灵紧随兆鹏入了党,孝文一心讨好父亲,却渐渐偏离了正道。半个世纪的画卷,展现了中国乱世下的众生相 本片根据已故作家陈忠实的同名小说改编。</li></ul><p><img src="https://5b0988e595225.cdn.sohucs.com/images/20180313/fb4ee7cd969643739c7d8af0b44a7fb4.jpeg" alt=""></p><h2 id="潜伏" tabindex="-1">潜伏 <a class="header-anchor" href="#潜伏" aria-label="Permalink to &quot;潜伏&quot;">​</a></h2><ul><li>2008-12-20 中国大陆</li><li>类型：剧情 谍战 爱情</li><li>主演：孙红雷 姚晨 沈傲君 祖峰 冯恩鹤</li><li>百科：1945年,正是抗日战争接近尾声之际,国、共、日三方的角力日趋激烈,平静的海面下暗流涌动。由于军统特务李海丰投靠南京汪伪政权,军统情报处成员余则成(孙红雷 饰)受命前往南京刺杀...</li></ul><p>最好看的谍战片，名场面太多了，必看！！！</p><p><img src="https://img2.baidu.com/it/u=1243491390,198826436&amp;fm=253&amp;fmt=auto&amp;app=138&amp;f=JPEG?w=890&amp;h=500" alt=""></p><h2 id="边水往事" tabindex="-1">边水往事 <a class="header-anchor" href="#边水往事" aria-label="Permalink to &quot;边水往事&quot;">​</a></h2><ul><li>2024-08-16 中国大陆</li><li>类型：剧情 冒险 探险</li><li>主演：郭麒麟 吴镇宇 尤勇智 江奇霖 齐溪</li><li>百科：三边坡,一处鱼龙混杂的热带异域,一个繁茂与衰败并生的斑驳之地。意外流落三边坡的打工小白沈星(郭麒麟 饰)遇到在多方势力间游走的三边坡和事佬猜叔(吴镇宇 饰),一场冒险,一段善良...</li></ul><p>非常好看的剧，各个演技在线，故事环环相扣，拍摄风格很别致。值得一看。</p><p><img src="https://pic.rmb.bdstatic.com/bjh/240814/58c86601d8bd535496524e8299d96269217.jpeg@h_1280" alt=""></p><h2 id="生存之民工" tabindex="-1">生存之民工 <a class="header-anchor" href="#生存之民工" aria-label="Permalink to &quot;生存之民工&quot;">​</a></h2><ul><li>2005-02-20 中国大陆</li><li>类型：剧情 生活 社会</li><li>主演：陶泽如 马少骅 高秀敏 孙松 雪村</li><li>百科：故事发生在东北小城松江市。一群来自全国各地的农民工,怀惴着形形色色的梦想,聚拢在“香榭丽舍”公寓的建筑工地上。</li></ul><p>非常真实的底层人的生活！！！</p><p><img src="https://gimg2.baidu.com/image_search/src=http%3A%2F%2Fsafe-img.xhscdn.com%2Fbw1%2F76a26cb3-cb43-44d1-95be-5cb53dfeaf52%3FimageView2%2F2%2Fw%2F1080%2Fformat%2Fjpg&amp;refer=http%3A%2F%2Fsafe-img.xhscdn.com&amp;app=2002&amp;size=f9999,10000&amp;q=a80&amp;n=0&amp;g=0n&amp;fmt=auto?sec=1733489299&amp;t=b51ae8c822974b7b3a6ac8856d9583a7" alt=""></p><h2 id="北平无战事" tabindex="-1">北平无战事 <a class="header-anchor" href="#北平无战事" aria-label="Permalink to &quot;北平无战事&quot;">​</a></h2><ul><li>2014-10-06 中国大陆</li><li>类型：剧情 战争</li><li>主演：刘烨 陈宝国 焦晃 倪大红 王庆祥</li><li>百科：1948年,国共两党的搏杀已经到了最为关键的时刻。国统区政经体制混乱失控,物价飞涨,贪官横行,国民政府的统治早就危如累卵,大厦将倾。与此同时,另一头国民党空军笕桥航校上校教官方...</li></ul><p>大腕挺多的</p><p><img src="https://photocdn.sohu.com/20141028/Img405543547.jpg" alt=""></p><h2 id="渗透" tabindex="-1">渗透 <a class="header-anchor" href="#渗透" aria-label="Permalink to &quot;渗透&quot;">​</a></h2><ul><li>2013-12-03 中国大陆</li><li>类型：谍战 战争 剧情</li><li>主演：沙溢 陈瑾 于越 曹炳琨 张佳宁</li><li>百科：故事发生在1945年的陪都重庆。国民党特训班学生许忠义(沙溢 饰)因留级奉命进入沈阳的军统组织,他的任务是打入中共部队做卧底,军统沈阳站特务头子陈明(赵纯阳 饰)不明就里,对许...</li></ul><p>非常非常好看，也很搞笑。笑死，强烈推荐</p><p><img src="https://i2.hitv.com/p1/20150417/1536116554C.jpg" alt=""></p><h2 id="扫毒风暴" tabindex="-1">扫毒风暴 <a class="header-anchor" href="#扫毒风暴" aria-label="Permalink to &quot;扫毒风暴&quot;">​</a></h2><ul><li>2025-07-12 中国大陆</li><li>类型：刑侦 涉案</li><li>主演：段奕宏 秦昊 于文文 吴幸键 刘欢 侯岩松 吴晓亮 张世 胡明</li><li>百科：该剧讲述了1995年，走私商卢少骅（秦昊饰）因生意变故发现冰毒的巨大利润，走上制毒贩毒的歧路，卧底回归的缉毒警察林强峰（段奕宏饰）为追查毒品线索调任西港市禁毒支队，与犯罪分子展开殊死较量的故事。</li></ul><p>很好看，强烈推荐</p><p><img src="https://img2.utuku.imgcdc.com/650x0/news/20250712/b009302c-b69f-41c0-884e-8605abe77388.jpg" alt=""></p><h2 id="棋士" tabindex="-1">棋士 <a class="header-anchor" href="#棋士" aria-label="Permalink to &quot;棋士&quot;">​</a></h2><ul><li>2025-03-25 中国大陆</li><li>类型：悬疑 犯罪</li><li>主演：王宝强 陈明昊 陈永胜 王智 李乃文 李梦 吴天琪 李若天 刘禹泽 李易祥 邢佳栋</li><li>百科：该剧讲述了21世纪初，围棋老师崔业（王宝强饰）在一次信用社抢劫案中被劫为人质，为自保协助劫匪逃脱，意外发现自己擅长的围棋能力可用于犯罪策划，从而一步步走向犯罪深渊。其哥哥崔伟（陈明昊饰）作为一名警察，试图引导他回归正道，但兄弟二人最终在黑白道路上渐行渐远，陷入命运博弈的故事</li></ul><p>很好看，强烈推荐</p><p><img src="https://th.bing.com/th/id/R.e7734821e23d706ca514b7e4a7e8adb1?rik=16kobBIrKDN9XA&amp;riu=http%3a%2f%2fctdsb.clouddiffuse.xyz%2fT-20250327152201-43b7ce4c-2f80-46db-b63e-120b61cf055b&amp;ehk=yLXnFlqHD0yeBJ%2b%2bZMr0UmmvTcqGRwargcz3uKy4oV4%3d&amp;risl=&amp;pid=ImgRaw&amp;r=0" alt=""></p><h2 id="漫长的季节" tabindex="-1">漫长的季节 <a class="header-anchor" href="#漫长的季节" aria-label="Permalink to &quot;漫长的季节&quot;">​</a></h2><ul><li>2023-04-22 中国大陆</li><li>类型：悬疑 犯罪</li><li>主演：范伟 秦昊 陈明昊 李庚希 刘奕铁 蒋奇明 刘琳 史彭元 侯岩松 林晓杰 王佳佳 杨一威 唐曾</li><li>百科：该剧讲述了出租车司机王响（范伟 饰）和妹夫龚彪（秦昊 饰）联手调查套牌车的过程中，意外发现了18年前碎尸案的线索，他们和退休警官马德胜（陈明昊 饰）重新踏上了追寻真相之路。故事跨越1997年、1998年和2016年三条时间线，揭示了东北小城桦林里几个家庭的人生变故和命运纠葛。</li></ul><p>封神之作！！！太强了，必看</p><p><img src="https://thfvnext.bing.com/th/id/OIP.M9Qylp6d0wUusAmwlcEOJgHaLH?r=0&amp;o=7&amp;cb=thfvnextrm=3&amp;rs=1&amp;pid=ImgDetMain&amp;o=7&amp;rm=3" alt=""></p><h2 id="沙尘暴" tabindex="-1">沙尘暴 <a class="header-anchor" href="#沙尘暴" aria-label="Permalink to &quot;沙尘暴&quot;">​</a></h2><ul><li>2025-03-28 中国大陆</li><li>类型：悬疑 犯罪</li><li>主演：段奕宏 王锵 张佳宁 张瑶 杨新鸣 黄小蕾 郑好 郑楚一 李春嫒 胡晓光 鲍鲲 土豆 黄婷婷 迟蓬</li><li>百科：该剧讲述了西北荒漠小城库鲁县发生一起跨越八年的锅炉焚尸案，基层民警陈江河（段奕宏饰）与市局刑警罗英玮（张瑶饰）联手重启调查，在证据缺失、证人记忆模糊的困境中，揭开隐藏在熟人社会下的罪恶网络。故事通过双线叙事穿插八年前后，深度剖析了极端环境下的人性抉择与命运挣扎。</li></ul><p>挺好看的，反转再反转，细节把控的很好。</p><p><img src="https://pic1.zhimg.com/v2-b4cbd54e5b2c688b9f99067f7b5befc9_r.jpg?source=1def8aca" alt=""></p><h2 id="雾柳镇" tabindex="-1">雾柳镇 <a class="header-anchor" href="#雾柳镇" aria-label="Permalink to &quot;雾柳镇&quot;">​</a></h2><ul><li>2009-01-08 中国大陆</li><li>类型：年代 爱情</li><li>主演：张国强 李钰 张光北 陶泽如 张桐 陈炜 周显欣</li><li>百科：该剧根据苏童的小说《米》和贾平凹的小说《五魁》《美穴地》改编，讲述了二十世纪二三十年代，进步青年柳云轩（张国强饰）在雾柳镇与当地恶霸柳爷（陶泽如饰）抗争，并带领劳苦大众从迷茫走向觉醒，最终投身抗日战场的故事。剧中交织了柳云轩与名角紫苏（李钰饰）等人的情感纠葛，展现了动荡年代下的人性与血性</li></ul><p>冲着张国强去的，当个下饭剧看看也行，6分吧</p><p><img src="https://th.bing.com/th/id/R.a5dd4122869f0e0ef989070c945aea42?rik=9e3tIVKZwKN9aw&amp;riu=http%3a%2f%2fpix2.tvzhe.com%2fthumb%2fdrama%2f10%2f433%2f270x360.jpg&amp;ehk=svfQ3E9fXxWR4JJdyAcwvOMa3p0Wg84b8xSKxDOuDDE%3d&amp;risl=&amp;pid=ImgRaw&amp;r=0" alt=""></p><h2 id="欢乐颂" tabindex="-1">欢乐颂 <a class="header-anchor" href="#欢乐颂" aria-label="Permalink to &quot;欢乐颂&quot;">​</a></h2><ul><li>2016-04-18 中国大陆</li><li>类型：都市 职场 女性</li><li>主演：刘涛 蒋欣 王子文 杨紫 乔欣 靳东 王凯 祖峰 杨烁 张陆</li><li>百科：该剧讲述了同住在欢乐颂小区22楼的五位背景各异、性格鲜明的女性——高冷海归安迪（刘涛饰）、职场精英樊胜美（蒋欣饰）、富家女曲筱绡（王子文饰）、普通上班族关雎尔（乔欣饰）和天真烂漫的邱莹莹（杨紫饰），从相互揣测到渐渐接纳彼此，共同面对职场、情感和家庭困境，在上海这座魔都中携手成长与蜕变的故事</li></ul><p>挺有意思的，很搞笑，强烈推荐看看。</p><p><img src="https://th.bing.com/th/id/R.784e9da6b149f652bd83b66c939ef281?rik=UjP4NlP6RXSO0Q&amp;riu=http%3a%2f%2fpic.caixin.com%2fblog%2fMon_1705%2f1494577593_cNuLdH.jpg&amp;ehk=TWnhRlOM2NcfyjpfKtmromEaq9OUZzMCI8d9B%2bFP%2bBU%3d&amp;risl=&amp;pid=ImgRaw&amp;r=0" alt=""></p><h2 id="以法之名" tabindex="-1">以法之名 <a class="header-anchor" href="#以法之名" aria-label="Permalink to &quot;以法之名&quot;">​</a></h2><ul><li>2025-06-24 中国大陆</li><li>类型：反腐 涉案 悬疑</li><li>主演：张译 李光洁 蒋欣 刘佳 冯嘉怡 杨烁 丁勇岱 王劲松 任重 白冰</li><li>百科：该剧讲述了海东省检察院检察官洪亮（张译 饰）、郑雅萍（蒋欣 饰）等人在复查东平市“万氏集团涉黑案”过程中，发现司法人员徇私枉法并牵出复杂利益网络。他们以举报线索为突破口，在调查检察官乔振兴离奇死亡案的同时，深挖背后保护伞，最终打掉黑恶势力“天龙集团”并查办司法工作人员职务犯罪，彰显司法公正的故事</li></ul><p><img src="https://www.spp.gov.cn/zdgz/202507/700875/images/fd0d40670b6440ef966f614a9e95e0bf.jpg" alt=""></p>',141)])])}const b=i(p,[["render",m]]);export{d as __pageData,b as default};
